fast_pseudocode:
# CORRECT: lambda grid reads autotuned tile sizes from meta
@triton.autotune(configs=[Config({'XBLOCK':512,'YBLOCK':16}, ...)], key=[...])
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: constexpr, XBLOCK: constexpr):
    ...

# Launch with dynamic grid that adapts to whichever config autotune selects
grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)

